using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ActivateStarBasedOnEffectPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Orion/ActivateStarBasedOnEffectPreviewDescription", order = 0)]
public class ActivateStarBasedOnEffectPreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		return (battleAction as ConjureAction).GetActivateAmount(GetAmountWithoutEquation(amountModified));
	}
}
